const app=document.getElementById('app');
const modalRoot=document.getElementById('modal-root');
const toastRoot=document.getElementById('toast-root');
let token='';
let me=null;
localStorage.removeItem('prometey_token');
let current='dashboard';
let equipmentFilter='all';
let mapFilter='all';
let openOrderId=null;

const money=n=>new Intl.NumberFormat('ru-RU').format(Math.round(Number(n)||0))+' ₽';
const pct=n=>(Number(n)||0).toFixed(1)+'%';
const esc=s=>String(s??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
// Права текущего пользователя (приходят с сервера в me.perms). Уровни — как в lib/access.js.
const PERM_LEVELS={crm:['none','own','read','all'],finance:['none','own','all'],documents:['none','own','all'],accounting:['none','read','edit'],feed:['read','post','moderate']};
function can(key,level='yes'){const p=me&&me.perms;if(!p)return !!me&&me.role==='director';if(p.admin)return true;const order=PERM_LEVELS[key]||['no','yes'];return order.indexOf(p[key])>=order.indexOf(level)}
const PAGE_RULES={dashboard:['crm','own'],leads:['crm','own'],objects:['crm','own'],orders:['crm','own'],equipment:['crm','own'],map:['crm','own'],clients:['crm','own'],finance:['finance','own'],documents:['documents','own'],accounting:['accounting','read'],integrations:['integrations','yes'],audit:['audit','yes']};
function pageAllowed(page){if(page==='admin')return can('users')||can('settings');const r=PAGE_RULES[page];return !r||can(r[0],r[1])}
function homePage(){return pageAllowed('dashboard')?'dashboard':'feed'}
const statusLabel=s=>({working:'В работе',planned:'Запланировано',done:'Завершён',available:'Свободна',maintenance:'ТО / ремонт',active:'Активен'}[s]||s||'—');
const unitLabel=u=>({shift:'смен',hour:'ч',trip:'рейс',unit:'ед.',day:'сут.',machine_hour:'маш.-ч',km:'км',ton:'т',m3:'м³'}[u]||String(u||'').replace(/^custom:/,''));
const statusBadge=s=>`badge badge-${s==='working'?'working':s==='available'?'available':s==='maintenance'?'maintenance':s==='planned'?'planned':'done'}`;
const ownBadge=o=>`<span class="badge ${o==='own'?'badge-own':'badge-rented'}">${o==='own'?'Своя':'Наёмная'}</span>`;
function toast(msg,bad=false){const el=document.createElement('div');el.className='toast'+(bad?' bad':'');el.textContent=msg;toastRoot.appendChild(el);setTimeout(()=>el.remove(),2600)}
async function api(path,opts={}){const headers={'Content-Type':'application/json',...(opts.headers||{})};if(token)headers.Authorization=`Bearer ${token}`;const res=await fetch(path,{credentials:'same-origin',...opts,headers});const data=await res.json().catch(()=>({}));if(res.status===401&&path!=='/api/login'){logout();throw new Error('Сессия завершена')}if(!res.ok)throw new Error(data.error||'Ошибка запроса');return data}
function logout(){stopDealChat();stopCallPlayers();fetch('/api/logout',{method:'POST',credentials:'same-origin',headers:token?{Authorization:'Bearer '+token}:{}}).catch(()=>{});current='dashboard';token='';me=null;localStorage.removeItem('prometey_token');localStorage.removeItem('prometey_user');renderLogin()}

function renderLogin(){
app.innerHTML=`<div class="login-shell">
  <section class="login-hero">
    <div class="brand-mark"><div class="brand-icon">P</div><span>ПРОМЕТЕЙ</span></div>
    <div class="hero-copy"><h1>Управляй техникой.<br>Контролируй прибыль.</h1><p>Отраслевая CRM для аренды и субаренды спецтехники. Объекты, несколько машин в заказе, своя и наёмная техника, роли, карта, документы и экономика.</p><div class="hero-pills"><span class="hero-pill">CRM</span><span class="hero-pill">Диспетчеризация</span><span class="hero-pill">Карта</span><span class="hero-pill">Финансы</span><span class="hero-pill">API-first</span></div></div>
    <div class="muted" id="login-version">ПРОМЕТЕЙ CRM</div>
  </section>
  <section class="login-side"><div class="login-card">
    <div class="brand-mark login-card-brand"><div class="brand-icon">P</div><span>ПРОМЕТЕЙ</span></div>
    <h2>Вход в систему</h2><div class="muted">Введите корпоративную учётную запись.</div>
    <form id="login-form"><label>Email</label><input class="field" id="login-email" type="email" autocomplete="username" required><label>Пароль</label><div class="pass-wrap"><input class="field" type="password" id="login-pass" autocomplete="current-password" required><button type="button" class="pass-eye" id="login-eye" aria-label="Показать пароль" title="Показать пароль">👁</button></div><div class="login-warn hidden" id="login-layout"></div><button class="btn btn-primary w100 login-submit">Войти</button></form><p class="muted small login-hint">Первый вход: логин <b>admin@prometey.local</b> и временный пароль из окна установщика. Забыли — запустите установщик ещё раз и нажмите «Выдать новый временный».</p><p class="small"><a href="#" id="login-policy">Политика обработки персональных данных</a></p>
    <button type="button" class="btn btn-ghost btn-sm" data-play-intro>Повторить заставку</button>
  </div></section></div>`;
const pass=document.getElementById('login-pass'),warn=document.getElementById('login-layout');
document.getElementById('login-eye').onclick=()=>{const show=pass.type==='password';pass.type=show?'text':'password';document.getElementById('login-eye').setAttribute('aria-label',show?'Скрыть пароль':'Показать пароль');pass.focus()};
const layout=e=>{const msgs=[];if(/[а-яё]/i.test(pass.value))msgs.push('В пароле русские буквы — переключите раскладку на английскую');if(e&&e.getModifierState&&e.getModifierState('CapsLock'))msgs.push('Включён Caps Lock');warn.textContent=msgs.join('. ');warn.classList.toggle('hidden',!msgs.length)};
pass.addEventListener('input',()=>layout());pass.addEventListener('keyup',layout);
document.getElementById('login-policy').onclick=e=>{e.preventDefault();if(typeof showPolicy==='function')showPolicy()};
(location.protocol==='file:'?Promise.reject():fetch('/api/config')).then(r=>r.json()).then(c=>{if(c.version)document.getElementById('login-version').textContent='ПРОМЕТЕЙ CRM · '+c.version}).catch(()=>{});
document.getElementById('login-form').onsubmit=async e=>{e.preventDefault();try{const r=await api('/api/login',{method:'POST',body:JSON.stringify({email:document.getElementById('login-email').value.trim(),password:document.getElementById('login-pass').value})});token='';me=r.user;renderApp()}catch(err){toast(err.message,true)}};
}

const navItems=[
 ['dashboard','⌂','Главная'],['feed','☰','Лента'],['leads','◎','Лиды'],['objects','▦','Объекты'],['orders','▤','Сделки'],['equipment','◫','Техника'],['map','⌖','Карта'],['clients','♙','Компании'],['finance','₽','Финансы'],['documents','▧','Документы'],['accounting','∑','Бухгалтерия'],['integrations','⇄','Интеграции'],['modules','◈','Модули'],['audit','≋','Журнал'],['admin','⚙','Администрирование']
];
function shell(){return `<div class="app-shell"><aside class="sidebar"><div class="brand-mark"><div class="brand-icon">P</div><span>ПРОМЕТЕЙ</span></div><nav class="nav">${navItems.filter(n=>pageAllowed(n[0])).map(n=>`<button data-page="${n[0]}" aria-label="${esc(n[2])}" class="${current===n[0]?'active':''}"><span class="icon">${n[1]}${n[0]==='feed'?'<span class="nav-badge" id="feed-badge" hidden></span>':''}</span><span>${n[2]}</span></button>`).join('')}<div class="nav-sep"></div><button data-page="about"><span class="icon">i</span><span>О сборке</span></button></nav><div class="side-user"><div class="role">${esc(me.perms?.roleName||(me.role==='director'?'Руководитель':'Менеджер'))}</div><div class="user-name strong">${esc(me.name)}</div><div class="muted small">${esc(me.email)}</div><div class="side-user-actions"><button class="btn btn-ghost btn-sm" id="my-profile">Профиль</button><button class="btn btn-ghost btn-sm" id="logout">Выйти</button></div></div></aside><main class="main"><header class="topbar"><div class="top-title">ПРОМЕТЕЙ CRM <span class="muted" id="top-version"></span></div><form id="global-search" class="global-search"><input aria-label="Поиск компаний и сделок" type="search" id="global-query" placeholder="Компания, сделка, ИНН, телефон" value="${esc(searchQuery)}"><button class="btn btn-light btn-sm">Найти</button></form></header><div class="content" id="page"></div></main></div>`}
function renderApp(){if(me&&window.__consentFor!==me.id&&typeof ensureConsent==='function')return ensureConsent();if(me&&me.mustChangePassword&&typeof forcePasswordChange==='function')return forcePasswordChange();app.innerHTML=shell();if(typeof mountLicenseBanner==='function')mountLicenseBanner();(location.protocol==='file:'?Promise.reject():fetch('/api/config')).then(r=>r.json()).then(c=>{const v=document.getElementById('top-version');if(v&&c.version)v.textContent='/ '+c.version}).catch(()=>{});document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{current=b.dataset.page;workspaceSelection=null;renderApp()});document.getElementById('logout').onclick=logout;document.getElementById('my-profile').onclick=()=>typeof openProfile==='function'?openProfile():toast('Профиль доступен в серверной версии',true);if(typeof startFeedBadge==='function')startFeedBadge();document.getElementById('global-search').onsubmit=e=>{e.preventDefault();searchQuery=val('global-query').trim();current='search';renderPage()};renderPage()}
async function renderPage(){stopDealChat();stopCallPlayers();const p=document.getElementById('page');p.innerHTML='<div class="muted">Загрузка…</div>';try{if(current==='search')await searchPage(p);else if(current==='dashboard')await dashboard(p);else if(current==='leads')await leadsPage(p);else if(current==='objects')await objects(p);else if(current==='orders')await orders(p);else if(current==='equipment')await equipment(p);else if(current==='map')await mapPage(p);else if(current==='clients')await clients(p);else if(current==='finance')await finance(p);else if(current==='documents')await documentsPage(p);else if(current==='feed')await feedPage(p);else if(current==='accounting')await accountingPage(p);else if(current==='admin')await adminPage(p);else if(current==='integrations')await integrationsPage(p);else if(current==='modules')await modules(p);else if(current==='audit')await auditPage(p);else about(p)}catch(err){p.innerHTML=`<div class="code-note">${esc(err.message)}</div>`}}

async function dashboard(p){const d=await api('/api/dashboard');p.innerHTML=`<div class="page-head"><div><h1>Доброе утро, ${esc(me.name.split(' ')[0])}</h1><p>${can('crm','read')?'Видно состояние всей компании.':'Видно состояние твоих объектов и заказов.'}</p></div><div class="actions"><button class="btn btn-dark" id="dash-new-order">+ Новый заказ</button></div></div>
<div class="kpi-grid"><div class="kpi"><div class="label">Активные объекты</div><div class="value">${d.counts.objects}</div><div class="hint">в зоне видимости</div></div><div class="kpi"><div class="label">Техника в работе</div><div class="value">${d.counts.working}</div><div class="hint">${d.counts.ownWorking} свои · ${d.counts.rentedWorking} наёмные</div></div><div class="kpi"><div class="label">Заказы</div><div class="value">${d.counts.orders}</div><div class="hint">текущий контур</div></div><div class="kpi"><div class="label">Выручка</div><div class="value money">${money(d.totals.revenue)}</div><div class="hint">по плановым строкам</div></div><div class="kpi"><div class="label">Плановая прибыль</div><div class="value money" style="color:var(--ok)">${money(d.totals.profit)}</div><div class="hint">до налогов</div></div></div>
<div class="ai-box"><h3>Prometey AI · модуль не подключён</h3><p>Основная CRM работает независимо от ИИ. После подключения AI будет выполнять только разрешённые действия с учётом роли пользователя.</p><div class="ai-prompts"><span class="ai-chip">Покажи свою технику в работе</span><span class="ai-chip">Что освобождается завтра?</span><span class="ai-chip">Какие заказы низкомаржинальные?</span></div></div>
<div class="grid-2"><div class="panel"><div class="panel-head"><h3>Последние заказы</h3><button class="btn btn-light btn-sm" data-goto="orders">Все заказы</button></div><div class="table-wrap"><table class="table"><thead><tr><th>Заказ</th><th>Клиент</th><th>Объект</th><th>Статус</th><th>Выручка</th><th>Прибыль</th></tr></thead><tbody>${d.recentOrders.map(o=>`<tr><td class="strong">${o.number}</td><td>${esc(o.client)}</td><td>${esc(o.object)}</td><td><span class="${statusBadge(o.status)}">${statusLabel(o.status)}</span></td><td>${money(o.revenue)}</td><td class="profit">${money(o.profit)}</td></tr>`).join('')}</tbody></table></div></div><div class="panel"><div class="panel-head"><h3>Требует внимания</h3></div><div class="panel-body"><ul class="list-clean">${d.alerts.map(a=>`<li class="alert-item"><span class="dot"></span><span>${esc(a)}</span></li>`).join('')}</ul></div></div></div>`;
document.querySelector('[data-goto="orders"]').onclick=()=>{current='orders';renderApp()};document.getElementById('dash-new-order').onclick=()=>openOrderCreate();}

async function modules(p){const list=await api('/api/modules');p.innerHTML=`<div class="page-head"><div><h1>Модули</h1><p>Коммерческая архитектура: базовая CRM + подключаемые возможности.</p></div></div><div class="module-grid">${list.map(m=>`<div class="module-card"><div style="display:flex;justify-content:space-between;gap:12px"><div><div class="strong">${esc(m.name)}</div><div class="muted small">${esc(m.description)}</div></div>${can('settings')?`<div class="switch ${m.enabled?'on':''}" data-module="${m.id}" data-enabled="${m.enabled}"><span></span></div>`:''}</div><div>${m.price?`<span class="module-price">${money(m.price)}</span><span class="muted"> / мес.</span>`:'<span class="badge badge-working">Включено в базу</span>'}</div></div>`).join('')}</div>${!can('settings')?'<div class="code-note" style="margin-top:14px">Менеджер видит доступные возможности, но подключение модулей выполняет руководитель.</div>':''}`;document.querySelectorAll('[data-module]').forEach(s=>s.onclick=async()=>{try{await api('/api/modules',{method:'POST',body:JSON.stringify({id:s.dataset.module,enabled:s.dataset.enabled!=='true'})});toast('Настройка модуля сохранена');renderPage()}catch(e){toast(e.message,true)}})}

async function auditPage(p){const PAGE=200;let q='',shown=0,done=false;
 p.innerHTML=`<div class="page-head"><div><h1>Журнал действий</h1><p>Единый audit trail — важная часть архитектуры «Прометея».</p></div></div><form class="list-toolbar audit-toolbar" id="audit-filter"><input class="field" type="search" id="audit-q" placeholder="Поиск по пользователю, действию, описанию" aria-label="Поиск по журналу"><button class="btn btn-light">Найти</button></form><div class="panel"><div class="table-wrap"><table class="table"><thead><tr><th>Время</th><th>Пользователь</th><th>Действие</th><th>Сущность</th><th>Описание</th></tr></thead><tbody id="audit-rows"></tbody></table></div><div class="audit-more-wrap"><button type="button" class="btn btn-light" id="audit-more" hidden>Показать ещё</button></div></div>`;
 const rows=p.querySelector('#audit-rows'),more=p.querySelector('#audit-more');
 const load=async reset=>{if(reset){shown=0;done=false;rows.innerHTML=''}const list=await api('/api/audit?limit='+(PAGE+1)+'&offset='+shown+(q?'&q='+encodeURIComponent(q):''));done=list.length<=PAGE;const page=list.slice(0,PAGE);shown+=page.length;rows.insertAdjacentHTML('beforeend',page.map(x=>`<tr><td>${new Date(x.at).toLocaleString('ru-RU')}</td><td>${esc(x.user)}</td><td class="strong">${esc(x.action)}</td><td>${esc(x.entity)}</td><td>${esc(x.details)}</td></tr>`).join(''));if(!shown)rows.innerHTML='<tr><td colspan="5" class="muted">Записей не найдено</td></tr>';more.hidden=done};
 p.querySelector('#audit-filter').onsubmit=e=>{e.preventDefault();q=p.querySelector('#audit-q').value.trim();load(true).catch(err=>toast(err.message,true))};
 more.onclick=()=>{more.disabled=true;load(false).catch(err=>toast(err.message,true)).finally(()=>more.disabled=false)};
 await load(true)}

async function mapPage(p){const [list,cfg]=await Promise.all([api('/api/map?ownership='+mapFilter),api('/api/config')]);p.innerHTML=`<div class="page-head"><div><h1>Карта техники</h1><p>${can('crm','read')?'Руководитель видит всю доступную технику и объекты.':'Менеджер видит технику, связанную с его объектами.'}</p></div><div class="actions"><div class="segmented">${[['all','Все'],['own','Своя'],['rented','Наёмная']].map(x=>`<button data-map-filter="${x[0]}" class="${mapFilter===x[0]?'active':''}">${x[1]}</button>`).join('')}</div></div></div><div class="map-shell"><div id="map" class="map-canvas"></div></div>`;document.querySelectorAll('[data-map-filter]').forEach(b=>b.onclick=()=>{mapFilter=b.dataset.mapFilter;renderPage()});if(cfg.yandexMapsApiKey)loadYandexMap(cfg.yandexMapsApiKey,list);else renderFallbackMap(list)}
function renderFallbackMap(list){const map=document.getElementById('map');map.className='map-fallback';map.innerHTML=`<div class="map-points">${list.map(e=>`<div class="map-point"><div style="display:flex;justify-content:space-between"><div class="strong">${esc(e.type)} · ${esc(e.model)}</div>${ownBadge(e.ownership)}</div><div class="muted small">${esc(e.plate)} · ${statusLabel(e.status)}</div><div style="margin-top:8px">${e.object?`📍 ${esc(e.object.name)}<div class="muted small">${esc(e.object.address)}</div>`:'<span class="muted">Сейчас не назначена на объект</span>'}</div><div class="muted small" style="margin-top:7px">${Number(e.lat).toFixed(4)}, ${Number(e.lng).toFixed(4)}</div></div>`).join('')}</div><div class="map-note"><b>Яндекс Карты готовы к подключению.</b><br>Добавь API-ключ в <code>config/config.json</code> или переменную <code>YANDEX_MAPS_API_KEY</code> — маркеры появятся на реальной карте.</div>`}
function loadYandexMap(key,list){const old=document.getElementById('ymaps-script');if(old)old.remove();const s=document.createElement('script');s.id='ymaps-script';s.src=`https://api-maps.yandex.ru/2.1/?apikey=${encodeURIComponent(key)}&lang=ru_RU`;s.onload=()=>ymaps.ready(()=>{const map=new ymaps.Map('map',{center:[55.75,37.61],zoom:9,controls:['zoomControl','fullscreenControl']});list.forEach(e=>{const pl=new ymaps.Placemark([e.lat,e.lng],{balloonContentHeader:`${esc(e.type)} · ${esc(e.model)}`,balloonContentBody:`${e.ownership==='own'?'Своя':'Наёмная'} · ${esc(e.plate)}<br>${e.object?esc(e.object.name):'Без объекта'}<br>${statusLabel(e.status)}`},{preset:e.ownership==='own'?'islands#blueAutoIcon':'islands#orangeAutoIcon'});map.geoObjects.add(pl)});if(list.length){const bounds=map.geoObjects.getBounds();if(bounds)map.setBounds(bounds,{checkZoomRange:true,zoomMargin:30})}});s.onerror=()=>renderFallbackMap(list);document.head.appendChild(s)}

function about(p){p.innerHTML=`<div class="page-head"><div><h1>О системе</h1><p>ПРОМЕТЕЙ CRM 1.0 · управление арендой и субарендой спецтехники.</p></div></div><div class="grid-2"><div class="panel"><div class="panel-head"><h3>Рабочий контур</h3></div><div class="panel-body"><ul><li>Роли руководитель / менеджер и серверные права доступа</li><li>Компании, сделки, объекты и несколько единиц техники в сделке</li><li>Своя / наёмная техника, назначения и смены</li><li>Плановая и фактическая экономика: оборот, затраты, прибыль и маржа</li><li>Рабочие столы компаний и сделок, задачи, заметки и общий чат</li><li>Импорт / экспорт контактов CSV</li><li>Журнал звонков и защищённые аудиозаписи</li><li>Счета и договоры: нумерация, PDF, реестр и статусы оплаты</li><li>Интеграционные шлюзы 1С, Битрикс24 и телефонии</li><li>Журнал действий и резервное копирование серверных данных</li></ul></div></div><div class="panel"><div class="panel-head"><h3>Подключаемые возможности</h3></div><div class="panel-body"><ul><li>Яндекс Карты — после установки API-ключа</li><li>1С / Битрикс24 — после настройки защищённых серверных реквизитов</li><li>Телефония Mango / Билайн / МТС / T2 / custom — через открытый шлюз</li><li>GPS / ГЛОНАСС — после подключения провайдера координат</li><li>Prometey AI, ЭДО и банковская сверка — отдельные интеграционные модули</li><li>Мультитенантный SaaS-контур PostgreSQL + RLS — следующий этап масштабирования</li></ul></div></div></div><div class="code-note" style="margin-top:16px"><b>Контур 1.0:</b> постоянное хранилище SQLite рассчитано на закрытый пилот одной компании. Для массового SaaS-развёртывания используется отдельная PostgreSQL-архитектура.</div>`}

function val(id){return document.getElementById(id)?.value||''}

async function openObjectCreate(){modal('Новый объект',`<div class="form-grid"><div class="form-group"><label>Название</label><input id="f-name" class="field" placeholder="ЖК Северный"></div><div class="form-group"><label>Адрес</label><input id="f-address" class="field" placeholder="Москва, ..."></div><div class="form-group"><label>Широта</label><input id="f-lat" class="field" value="55.75"></div><div class="form-group"><label>Долгота</label><input id="f-lng" class="field" value="37.61"></div><div class="form-group full"><label>Комментарий</label><textarea id="f-note" class="field" rows="3"></textarea></div></div>`,()=>api('/api/objects',{method:'POST',body:JSON.stringify({name:val('f-name'),address:val('f-address'),lat:val('f-lat'),lng:val('f-lng'),note:val('f-note')})}))}
async function openEquipmentCreate(){const partners=await api('/api/partners');modal('Новая техника',`<div class="form-grid"><div class="form-group"><label>Принадлежность</label><select id="f-own" class="field"><option value="rented">Наёмная</option>${can('equipment')?'<option value="own">Собственная</option>':''}</select></div><div class="form-group"><label>Тип</label><input id="f-type" class="field" placeholder="Экскаватор"></div><div class="form-group"><label>Марка / модель</label><input id="f-model" class="field" placeholder="CAT 320"></div><div class="form-group"><label>Госномер</label><input id="f-plate" class="field"></div><div class="form-group"><label>Владелец</label><input id="f-owner" class="field" placeholder="ООО ТехРесурс"></div><div class="form-group"><label>Машинист</label><input id="f-driver" class="field"></div><div class="form-group"><label>Ставка клиенту</label><input id="f-sale" type="number" class="field" value="30000"></div><div class="form-group"><label>Закупочная ставка</label><input id="f-buy" type="number" class="field" value="24000"></div><div class="form-group"><label>Широта</label><input id="f-lat" class="field" value="55.75"></div><div class="form-group"><label>Долгота</label><input id="f-lng" class="field" value="37.61"></div></div>`,()=>api('/api/equipment',{method:'POST',body:JSON.stringify({ownership:val('f-own'),type:val('f-type'),model:val('f-model'),plate:val('f-plate'),ownerName:val('f-owner'),driver:val('f-driver'),saleRate:val('f-sale'),purchaseRate:val('f-buy'),lat:val('f-lat'),lng:val('f-lng')})}))}
async function openAssignment(objectId,equipmentList,ordersList){const relevant=ordersList.filter(o=>o.objectId===objectId);modal('Назначить технику на объект',`<div class="form-grid"><div class="form-group full"><label>Техника</label><select id="f-eq" class="field">${equipmentList.map(e=>`<option value="${e.id}">${esc(e.type)} · ${esc(e.model)} · ${esc(e.plate)} · ${e.ownership==='own'?'своя':'наёмная'}</option>`).join('')}</select></div><div class="form-group"><label>Заказ</label><select id="f-order" class="field"><option value="">Без привязки</option>${relevant.map(o=>`<option value="${o.id}">${o.number}</option>`).join('')}</select></div><div class="form-group"><label>Статус</label><select id="f-status" class="field"><option value="planned">Запланировано</option><option value="working">В работе</option></select></div><div class="form-group"><label>Начало</label><input id="f-start" type="datetime-local" class="field"></div><div class="form-group"><label>Окончание</label><input id="f-end" type="datetime-local" class="field"></div><div class="form-group full"><label>Детализация работы</label><input id="f-details" class="field" placeholder="Котлован, вывоз грунта, монтаж..."></div></div>`,()=>api('/api/assignments',{method:'POST',body:JSON.stringify({objectId,equipmentId:val('f-eq'),orderId:val('f-order'),status:val('f-status'),start:val('f-start'),end:val('f-end'),details:val('f-details')})}))}
// 0.4 — editable deals, archive, search and period reports.
const listState={};
const financeState={from:'',to:'',mode:'plan',ownership:'all'};
let searchQuery='';
const empty=(text='Записей не найдено')=>`<div class="empty-state">${esc(text)}</div>`;
const localDate=()=>new Date().toLocaleDateString('sv-SE',{timeZone:'Europe/Moscow'});
const dt=v=>v?(v.length===10?v+'T08:00':v.slice(0,16)):'';
const input=(id,label,value='',type='text',required=false,extra='')=>`<div class="form-group"><label for="${id}">${esc(label)}${required?' *':''}</label><input class="field" id="${id}" type="${type}" value="${esc(value)}" ${required?'required':''} ${extra}></div>`;
function select(id,label,items,value='',required=false){return `<div class="form-group"><label for="${id}">${esc(label)}${required?' *':''}</label><select class="field" id="${id}" ${required?'required':''}>${items.map(([v,t])=>`<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(t)}</option>`).join('')}</select></div>`}
const ownerships=[['','Выберите'],['own','Наша техника'],['rented','Наёмная техника'],['mixed','Своя и наёмная']];
const commentField=v=>`<div class="form-group full"><label for="f-note">Комментарий *</label><textarea class="field" id="f-note" required rows="3">${esc(v||'')}</textarea></div>`;
function requestFields(x,isCompany=false){return input('f-address','Адрес',x.address,'text',true)+input('f-type','Вид техники',x.equipmentType,'text',true,'list="equipment-types"')+'<datalist id="equipment-types"><option>Экскаватор</option><option>Экскаватор-погрузчик</option><option>Автокран</option><option>Самосвал</option><option>Фронтальный погрузчик</option></datalist>'+select('f-own','Принадлежность техники',ownerships,x.ownership,true)+input('f-start',isCompany?'Дата и время заявки':'Дата и время начала',dt(isCompany?x.requestAt:x.start),'datetime-local',true)+(isCompany?'':input('f-end','Дата и время окончания',dt(x.end),'datetime-local'))+commentField(x.note)}
function commonValues(){return {address:val('f-address'),equipmentType:val('f-type'),ownership:val('f-own'),note:val('f-note')}}
function stateFor(kind){return listState[kind]||(listState[kind]={q:'',archive:'active',sort:kind==='orders'?'start':'name',dir:kind==='orders'?'desc':'asc'})}
function listUrl(kind){return '/api/'+kind+'?'+new URLSearchParams(stateFor(kind))}
function toolbar(kind,sorts){const s=stateFor(kind);return `<form class="list-toolbar" id="list-toolbar"><div class="search-field"><label class="sr-only" for="list-search">Поиск</label><input class="field" type="search" id="list-search" placeholder="${kind==='orders'||kind==='clients'?'Название, ИНН или телефон':'Название, адрес или техника'}" value="${esc(s.q)}"><button class="btn btn-dark">Найти</button></div><label>Показывать<select class="field" id="archive-filter">${[['active','Активные'],['archived','Архив'],['all','Все записи']].map(([v,t])=>`<option value="${v}" ${s.archive===v?'selected':''}>${t}</option>`).join('')}</select></label><label>Сортировка<select class="field" id="sort-filter">${sorts.map(([v,t])=>`<option value="${v}" ${s.sort===v?'selected':''}>${t}</option>`).join('')}</select></label><label>Порядок<select class="field" id="sort-direction"><option value="asc" ${s.dir==='asc'?'selected':''}>По возрастанию</option><option value="desc" ${s.dir==='desc'?'selected':''}>По убыванию</option></select></label></form>`}
function bindToolbar(kind){const update=()=>{Object.assign(stateFor(kind),{q:val('list-search'),archive:val('archive-filter'),sort:val('sort-filter'),dir:val('sort-direction')});renderPage()};document.getElementById('list-toolbar').onsubmit=e=>{e.preventDefault();update()};['archive-filter','sort-filter','sort-direction'].forEach(id=>document.getElementById(id).onchange=update)}
const archiveBadge=x=>x.archivedAt?'<span class="badge">В архиве</span>':'';
function archiveButton(x){return x.canEdit===false?'':`<button class="btn btn-light btn-sm archive-action" data-id="${esc(x.id)}" data-action="${x.archivedAt?'restore':'archive'}">${x.archivedAt?'Восстановить':'В архив'}</button>`}
function bindArchive(kind){document.querySelectorAll('.archive-action').forEach(b=>b.onclick=()=>{modal(b.dataset.action==='archive'?'Переместить в архив?':'Восстановить запись?',`<p>Запись ${b.dataset.action==='archive'?'исчезнет из активного списка. История и суммы в финансовых отчётах сохранятся.':'снова появится в активном списке.'}</p>`,()=>api('/api/'+kind+'/'+b.dataset.id+'/'+b.dataset.action,{method:'POST'}),b.dataset.action==='archive'?'В архив':'Восстановить')})}
async function legacyClients(p){const list=await api(listUrl('clients'));p.innerHTML=`<div class="page-head"><div><h1>Компании</h1><p>Контакты заказчиков и параметры их заявок.</p></div><button class="btn btn-primary" id="add-client">+ Компания</button></div>${toolbar('clients',[['name','По названию'],['inn','По ИНН'],['requestAt','По дате заявки'],['createdAt','По дате создания']])}<div class="panel"><div class="table-wrap"><table class="table"><thead><tr><th>Компания</th><th>ИНН / телефон</th><th>Заявка</th><th>Действия</th></tr></thead><tbody>${list.map(c=>`<tr><td><b>${esc(c.name)}</b> ${archiveBadge(c)}<div class="muted small">${esc(c.address||'Адрес не указан')}</div></td><td>${esc(c.inn||'—')}<br>${esc(c.phone||'—')}</td><td>${esc(c.equipmentType||'—')}<div class="muted small">${esc(c.requestAt?.replace('T',' ')||'Дата не указана')}</div></td><td><div class="actions">${!c.archivedAt&&c.canEdit?`<button class="btn btn-light btn-sm edit-client" data-id="${esc(c.id)}">Редактировать</button>`:''}${archiveButton(c)}</div></td></tr>`).join('')}</tbody></table>${!list.length?empty():''}</div></div>`;bindToolbar('clients');bindArchive('clients');document.getElementById('add-client').onclick=()=>openClientCreate();document.querySelectorAll('.edit-client').forEach(b=>b.onclick=()=>openClientCreate(list.find(x=>x.id===b.dataset.id)))}
async function openClientCreate(x={}){modal(x.id?'Редактировать компанию':'Новая компания',`<p class="muted">* Обязательные поля. Дата и техника — параметры заявки компании.</p><div class="form-grid">${input('f-name','Название компании',x.name,'text',true)}${input('f-inn','ИНН',x.inn)}${input('f-kpp','КПП',x.kpp)}${input('f-phone','Телефон',x.phone,'tel')}${input('f-email','Email',x.email,'email')}${input('f-legal-address','Юридический адрес',x.legalAddress||x.address)}${requestFields(x,true)}</div>`,()=>api('/api/clients'+(x.id?'/'+x.id:''),{method:x.id?'PATCH':'POST',body:JSON.stringify({...commonValues(),name:val('f-name'),inn:val('f-inn'),kpp:val('f-kpp'),phone:val('f-phone'),email:val('f-email'),legalAddress:val('f-legal-address'),requestAt:val('f-start')})}))}
async function legacyOrders(p){const list=await api(listUrl('orders'));p.innerHTML=`<div class="page-head"><div><h1>Сделки / заявки</h1><p>Несколько машин, отдельные ставки и периоды работы.</p></div><button class="btn btn-primary" id="add-order">+ Сделка</button></div>${toolbar('orders',[['start','По дате работ'],['name','По названию'],['client','По компании'],['revenue','По обороту'],['number','По номеру']])}<div id="orders-list">${list.map(o=>`<div class="order-card"><div class="order-main"><div><div class="order-number">${esc(o.number)}</div><b>${esc(o.name)}</b><div class="muted small">${esc(o.start?.replace('T',' '))}</div></div><div><b>${esc(o.client)}</b><div class="muted small">${esc(o.inn)} · ${esc(o.phone)}</div><div class="muted small">${esc(o.address||o.object)}</div></div><div><span class="${statusBadge(o.status)}">${esc(statusLabel(o.status))}</span> ${archiveBadge(o)}<div class="muted small">${esc(o.equipmentType||'')}</div></div><div><div class="muted small">Плановый оборот</div><b>${money(o.revenue)}</b></div><div class="actions">${!o.archivedAt&&o.canEdit!==false?`<button class="btn btn-light btn-sm edit-order" data-id="${esc(o.id)}">Редактировать</button>`:''}${archiveButton(o)}</div><button class="btn btn-light btn-sm order-toggle" data-id="${esc(o.id)}">${openOrderId===o.id?'Скрыть':'Техника и суммы'}</button></div>${openOrderId===o.id?'<div class="order-detail" data-detail="'+esc(o.id)+'"></div>':''}</div>`).join('')||empty()}</div>`;bindToolbar('orders');bindArchive('orders');document.getElementById('add-order').onclick=()=>openOrderCreate();document.querySelectorAll('.edit-order').forEach(b=>b.onclick=()=>openOrderCreate(list.find(x=>x.id===b.dataset.id)));document.querySelectorAll('.order-toggle').forEach(b=>b.onclick=()=>{openOrderId=openOrderId===b.dataset.id?null:b.dataset.id;renderPage()});const opened=list.find(o=>o.id===openOrderId);if(opened)await renderOrderDetail(opened.id,opened)}
async function openOrderCreate(x={}){const [cs,os]=await Promise.all([api('/api/clients?archive=all'),api('/api/objects?archive=all')]);const clients=cs.filter(c=>!c.archivedAt||c.id===x.clientId),objects=os.filter(o=>!o.archivedAt||o.id===x.objectId);if(!clients.length)return toast('Сначала добавьте компанию в разделе «Компании»',true);if(!objects.length)return toast('Сначала добавьте объект в разделе «Объекты»',true);modal(x.id?'Редактировать сделку':'Новая сделка',`<p class="muted">* Обязательные поля. Время указывается по Москве.</p><div class="form-grid">${input('f-name','Название сделки',x.name||x.number,'text',true)}${select('f-client','Компания',[['','Выберите компанию'],...clients.map(c=>[c.id,c.name])],x.clientId,true)}${input('f-client-inn','ИНН компании — поиск по базе',clients.find(c=>c.id===x.clientId)?.inn||'','text')}${select('f-object','Объект',[['','Выберите объект'],...objects.map(o=>[o.id,o.name])],x.objectId,true)}${select('f-status','Статус',[['planned','Запланирована'],['working','В работе'],['done','Завершена'],['cancelled','Отменена']],x.status||'planned')}${requestFields(x)}</div>`,()=>api('/api/orders'+(x.id?'/'+x.id:''),{method:x.id?'PATCH':'POST',body:JSON.stringify({...commonValues(),name:val('f-name'),clientId:val('f-client'),objectId:val('f-object'),start:val('f-start'),end:val('f-end'),status:val('f-status')})}));document.getElementById('f-client-inn').onchange=()=>{const inn=val('f-client-inn').replace(/\D/g,'');if(!inn)return;const matches=clients.filter(c=>String(c.inn||'').replace(/\D/g,'')===inn);if(matches.length===1){document.getElementById('f-client').value=matches[0].id;document.getElementById('f-client').dispatchEvent(new Event('change'));toast('Компания найдена по ИНН: '+matches[0].name)}else if(!matches.length)toast('Компания с таким ИНН отсутствует в CRM. Сначала добавьте её в «Компании».',true);else toast('Найдено несколько компаний с таким ИНН. Выберите нужную.',true)};document.getElementById('f-client').onchange=()=>{const c=clients.find(c=>c.id===val('f-client'));if(!c)return;document.getElementById('f-client-inn').value=c.inn||'';for(const [id,k] of [['f-address','address'],['f-type','equipmentType'],['f-own','ownership'],['f-start','requestAt'],['f-note','note']]){const el=document.getElementById(id);if(!el.value&&c[k])el.value=c[k]}};document.getElementById('f-object').onchange=()=>{const o=objects.find(o=>o.id===val('f-object'));if(o)document.getElementById('f-address').value=o.address||''}}
async function renderOrderDetail(id,order){const box=document.querySelector(`[data-detail="${id}"]`);if(!box)return;const d=await api('/api/order-items?orderId='+encodeURIComponent(id));box.innerHTML=`<p>${esc(order.note||'')}</p><div class="actions spread"><b>Техника в сделке · ${d.items.length}</b>${!order.archivedAt&&order.canEdit!==false?'<button class="btn btn-dark btn-sm" id="add-line">+ Добавить технику</button>':''}</div><div class="table-wrap"><table class="table"><thead><tr><th>Техника / даты</th><th>Количество</th><th>Клиенту</th><th>Себестоимость</th><th>Доп. расходы</th><th>Действия</th></tr></thead><tbody>${d.items.map(i=>`<tr><td><b>${esc(i.equipment?.type)} · ${esc(i.equipment?.model)}</b><div class="muted small">${esc(i.start||order.start?.slice(0,10))} — ${esc(i.end||order.end?.slice(0,10))}</div></td><td>${i.quantity} ${unitLabel(i.unit)}</td><td>${money(i.saleRate)}</td><td>${money(i.purchaseRate)}</td><td>${money(i.extras)}</td><td>${!order.archivedAt&&order.canEdit!==false?`<button class="btn btn-light btn-sm edit-line" data-id="${esc(i.id)}">Изменить</button> <button class="btn btn-light btn-sm remove-line" data-id="${esc(i.id)}">Убрать</button>`:(order.archivedAt?'Архив':'Только просмотр')}</td></tr>`).join('')}</tbody></table>${!d.items.length?empty('Добавьте технику, чтобы рассчитать стоимость сделки'):''}</div><div class="summary-strip"><span>Оборот: <b>${money(d.totals.revenue)}</b></span><span>Затраты: <b>${money(d.totals.cost)}</b></span><span>Прибыль: <b>${money(d.totals.profit)}</b></span></div>`;const add=box.querySelector('#add-line');if(add)add.onclick=()=>openOrderLineCreate(id,{},order);box.querySelectorAll('.edit-line').forEach(b=>b.onclick=()=>openOrderLineCreate(id,d.items.find(i=>i.id===b.dataset.id),order));box.querySelectorAll('.remove-line').forEach(b=>b.onclick=()=>modal('Убрать позицию из расчёта?','<p>Плановые суммы сделки будут пересчитаны. Уже внесённые суммы фактических смен сохранятся.</p>',()=>api('/api/order-items/'+b.dataset.id,{method:'DELETE'}),'Убрать'))}
async function openOrderLineCreate(orderId,x={},order={}){const all=await api('/api/equipment?archive=all');const eq=all.filter(e=>!e.archivedAt||e.id===x.equipmentId);if(!eq.length)return toast('Сначала добавьте технику',true);modal(x.id?'Редактировать позицию':'Добавить технику',`<div class="form-grid">${select('f-eq','Техника',eq.map(e=>[e.id,`${e.type} · ${e.model} · ${e.ownership==='own'?'своя':'наёмная'}`]),x.equipmentId||eq[0].id,true)}${select('f-unit','Единица расчёта',[['shift','Смена'],['hour','Час'],['trip','Рейс'],['unit','Единица'],['day','Сутки'],['machine_hour','Машино-час'],['km','Км'],['ton','Тонна'],['m3','м³']],x.unit||'shift')}${input('f-qty','Количество',x.quantity??1,'number',true,'min="0.01" step="0.01"')}${input('f-sale','Ставка клиенту',x.saleRate??eq[0].saleRate,'number',true,'min="0" step="0.01"')}${input('f-buy','Закупочная / внутренняя себестоимость',x.purchaseRate??eq[0].purchaseRate,'number',true,'min="0" step="0.01"')}${input('f-extra','Дополнительные расходы',x.extras??0,'number',true,'min="0" step="0.01"')}${input('f-start','Начало работы',x.start||order.start?.slice(0,10),'date',true)}${input('f-end','Окончание работы',x.end||order.end?.slice(0,10),'date',true)}${input('f-note','Комментарий',x.note)}</div>`,()=>api('/api/order-items'+(x.id?'/'+x.id:''),{method:x.id?'PATCH':'POST',body:JSON.stringify({orderId,equipmentId:val('f-eq'),unit:val('f-unit'),quantity:val('f-qty'),saleRate:val('f-sale'),purchaseRate:val('f-buy'),extras:val('f-extra'),start:val('f-start'),end:val('f-end'),note:val('f-note')})}));document.getElementById('f-eq').onchange=()=>{const e=eq.find(e=>e.id===val('f-eq'));document.getElementById('f-sale').value=e.saleRate;document.getElementById('f-buy').value=e.purchaseRate}}
async function objects(p){const [list,equipmentList,ordersList]=await Promise.all([api(listUrl('objects')),api('/api/equipment'),api('/api/orders')]);p.innerHTML=`<div class="page-head"><div><h1>Объекты</h1><p>Назначения техники и смены по дням.</p></div><button class="btn btn-primary" id="add-object">+ Объект</button></div>${toolbar('objects',[['name','По названию'],['address','По адресу'],['createdAt','По дате создания']])}<div class="cards">${list.map(o=>`<div class="card"><h3>${esc(o.name)} ${archiveBadge(o)}</h3><p class="muted">${esc(o.address)}</p><div class="equip-list">${o.assignments.map(a=>`<div class="equip-row"><span>${esc(a.equipment?.type)} · ${esc(a.equipment?.model)}</span>${ownBadge(a.equipment?.ownership)}</div>`).join('')||'<p class="muted">Техника пока не назначена</p>'}</div><div class="actions">${!o.archivedAt?`<button class="btn btn-light btn-sm assign-btn" data-id="${esc(o.id)}">+ Назначить технику</button><button class="btn btn-light btn-sm shift-btn" data-id="${esc(o.id)}">Смены</button>`:''}${archiveButton(o)}</div></div>`).join('')||empty()}</div>`;bindToolbar('objects');bindArchive('objects');document.getElementById('add-object').onclick=()=>openObjectCreate();document.querySelectorAll('.assign-btn').forEach(b=>b.onclick=()=>openAssignment(b.dataset.id,equipmentList,ordersList));document.querySelectorAll('.shift-btn').forEach(b=>b.onclick=()=>showShifts(list.find(o=>o.id===b.dataset.id)))}
async function equipment(p){const s=stateFor('equipment');if(s.sort==='name')s.sort='type';const list=await api(listUrl('equipment')+'&ownership='+equipmentFilter);p.innerHTML=`<div class="page-head"><div><h1>Техника</h1><p>Наш парк и привлечённые машины.</p></div><button class="btn btn-primary" id="add-equipment">+ Техника</button></div>${toolbar('equipment',[['type','По виду техники'],['model','По модели'],['saleRate','По ставке']])}<div class="segmented">${[['all','Все'],['own','Наша'],['rented','Наёмная']].map(([v,t])=>`<button data-filter="${v}" class="${equipmentFilter===v?'active':''}">${t}</button>`).join('')}</div><div class="panel"><div class="table-wrap"><table class="table"><thead><tr><th>Техника</th><th>Принадлежность</th><th>Машинист</th><th>Ставка</th><th>Действия</th></tr></thead><tbody>${list.map(e=>`<tr><td><b>${esc(e.type)} · ${esc(e.model)}</b> ${archiveBadge(e)}<div class="muted">${esc(e.plate)}</div></td><td>${ownBadge(e.ownership)}<div>${esc(e.ownerName)}</div></td><td>${esc(e.driver)}</td><td>${money(e.saleRate)}</td><td>${archiveButton(e)}</td></tr>`).join('')}</tbody></table>${!list.length?empty():''}</div></div>`;bindToolbar('equipment');bindArchive('equipment');document.getElementById('add-equipment').onclick=()=>openEquipmentCreate();document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{equipmentFilter=b.dataset.filter;renderPage()})}
async function finance(p){const d=await api('/api/finance?'+new URLSearchParams(financeState));p.innerHTML=`<div class="page-head"><div><h1>Финансы</h1><p>${can('finance','all')?'Все сделки компании':'Ваши сделки'} · включая архивные, без отменённых.</p></div></div><form id="finance-filter" class="list-toolbar">${input('period-from','Период с',financeState.from,'date')}${input('period-to','По включительно',financeState.to,'date')}${select('finance-mode','Расчёт',[['plan','Плановые работы'],['actual','Фактические смены']],financeState.mode)}${select('finance-own','Техника',[['all','Вся'],['own','Наша'],['rented','Наёмная']],financeState.ownership)}<button class="btn btn-primary">Показать</button><button type="button" class="btn btn-light" id="all-time">За всё время</button></form><p class="muted">${d.mode==='plan'?'Плановый оборот распределяется равномерно по календарным дням работы каждой позиции. Это стоимость работ, а не поступившие оплаты.':'Факт рассчитывается по дате смены и указанным в ней оплачиваемому количеству и ставкам. Это стоимость работ, а не поступившие оплаты.'}</p>${d.undated?`<div class="code-note">${d.undated} позиций без корректных дат не вошли в отчёт. Укажите даты в сделках.</div>`:''}${d.unpriced?`<div class="code-note">${d.unpriced} смен без расчёта не вошли в суммы. Заполните ставки в разделе «Объекты → Смены».</div>`:''}<div class="kpi-grid finance-kpis"><div class="kpi"><div class="label">Оборот за период</div><div class="value money">${money(d.totals.revenue)}</div></div><div class="kpi"><div class="label">Себестоимость</div><div class="value money">${money(d.totals.cost)}</div></div><div class="kpi"><div class="label">Прибыль до налогов</div><div class="value money">${money(d.totals.profit)}</div></div></div><div class="panel"><div class="panel-head"><h3>Оборот по технике</h3></div><div class="table-wrap"><table class="table"><thead><tr><th>Техника</th><th>Сделок</th><th>Оборот</th><th>Затраты</th><th>Прибыль</th></tr></thead><tbody>${d.equipment.map(e=>`<tr><td><b>${esc(e.type)} · ${esc(e.model)}</b><div>${esc(e.plate)} ${ownBadge(e.ownership)}</div></td><td>${e.orderCount}</td><td>${money(e.revenue)}</td><td>${money(e.cost)}</td><td>${money(e.profit)}</td></tr>`).join('')}</tbody></table>${!d.equipment.length?empty('Нет работ за выбранный период'):''}</div></div><div class="panel" style="margin-top:16px"><div class="panel-head"><h3>По сделкам</h3></div><div class="table-wrap"><table class="table"><thead><tr><th>Сделка</th><th>Компания</th><th>Оборот</th><th>Затраты</th><th>Прибыль</th></tr></thead><tbody>${d.orders.map(o=>`<tr><td>${esc(o.number)} · ${esc(o.name)} ${archiveBadge(o)}</td><td>${esc(o.client)}</td><td>${money(o.revenue)}</td><td>${money(o.cost)}</td><td>${money(o.profit)}</td></tr>`).join('')}</tbody></table></div></div>`;document.getElementById('finance-filter').onsubmit=e=>{e.preventDefault();if(val('period-from')&&val('period-to')&&val('period-from')>val('period-to'))return toast('Начало периода не может быть позже окончания',true);Object.assign(financeState,{from:val('period-from'),to:val('period-to'),mode:val('finance-mode'),ownership:val('finance-own')});renderPage()};document.getElementById('all-time').onclick=()=>{financeState.from='';financeState.to='';renderPage()}}
async function showShifts(obj){const shifts=(await api('/api/shifts')).filter(s=>obj.assignments.some(a=>a.id===s.assignmentId));modal('Смены · '+obj.name,`<button type="button" class="btn btn-primary" id="new-shift">+ Смена</button>${shifts.map(s=>{const a=obj.assignments.find(a=>a.id===s.assignmentId);return `<div class="shift-row"><span><b>${esc(s.date)}</b> · ${esc(a.equipment?.model)} · ${s.hours} ч<br><small>${s.billableQuantity==null?'Сумма не заполнена':money(s.billableQuantity*s.saleRate)}</small></span><button type="button" class="btn btn-light edit-shift" data-id="${esc(s.id)}">Редактировать</button></div>`}).join('')||empty('Смен пока нет')}`,async()=>{},'Закрыть');document.getElementById('new-shift').onclick=()=>openShiftForObject(obj.id,obj);document.querySelectorAll('.edit-shift').forEach(b=>b.onclick=()=>openShiftForObject(obj.id,obj,shifts.find(s=>s.id===b.dataset.id)))}
async function openShiftForObject(objectId,obj,x={}){const ass=obj.assignments||[];if(!ass.length)return toast('Сначала назначьте технику на объект',true);const a=ass.find(a=>a.id===x.assignmentId)||ass[0];const eq=a.equipment||{};const pricing=a.orderId?(await api('/api/order-items?orderId='+encodeURIComponent(a.orderId))).items.find(i=>i.equipmentId===a.equipmentId):null;modal(x.id?'Редактировать смену':'Новая смена',`<p class="muted">Укажите оплачиваемое количество отдельно: простой и переработка не добавляются к сумме автоматически.</p><div class="form-grid">${select('f-a','Техника',ass.map(a=>[a.id,`${a.equipment?.type} · ${a.equipment?.model}`]),a.id,true)}${input('f-date','Дата',x.date||localDate(),'date',true)}${input('f-hours','Фактические часы',x.hours??8,'number',true,'min="0" max="24" step="0.5"')}${input('f-down','Простой, ч',x.downtime??0,'number',true,'min="0" max="24" step="0.5"')}${input('f-over','Переработка, ч',x.overtime??0,'number',true,'min="0" max="24" step="0.5"')}${input('f-over-sale','Ставка переработки / час',x.overtimeSaleRate??0,'number',true,'min="0" step="0.01"')}${input('f-over-buy','Себестоимость переработки / час',x.overtimePurchaseRate??0,'number',true,'min="0" step="0.01"')}${select('f-unit','Единица расчёта',[['shift','Смена'],['hour','Час'],['trip','Рейс'],['unit','Единица'],['day','Сутки'],['machine_hour','Машино-час'],['km','Км'],['ton','Тонна'],['m3','м³']],x.unit||pricing?.unit||'shift')}${input('f-qty','Оплачиваемое количество',x.billableQuantity??1,'number',true,'min="0" step="0.01"')}${input('f-sale','Ставка клиенту',x.saleRate??pricing?.saleRate??eq.saleRate??0,'number',true,'min="0" step="0.01"')}${input('f-buy','Себестоимость',x.purchaseRate??pricing?.purchaseRate??eq.purchaseRate??0,'number',true,'min="0" step="0.01"')}${input('f-extra','Дополнительные расходы',x.extras??0,'number',true,'min="0" step="0.01"')}${input('f-comment','Комментарий',x.comment)}</div>`,()=>api('/api/shifts'+(x.id?'/'+x.id:''),{method:x.id?'PATCH':'POST',body:JSON.stringify({assignmentId:val('f-a'),date:val('f-date'),hours:val('f-hours'),downtime:val('f-down'),overtime:val('f-over'),overtimeSaleRate:val('f-over-sale'),overtimePurchaseRate:val('f-over-buy'),comment:val('f-comment'),unit:val('f-unit'),billableQuantity:val('f-qty'),saleRate:val('f-sale'),purchaseRate:val('f-buy'),extras:val('f-extra')})}));document.getElementById('f-a').onchange=async()=>{const a=ass.find(a=>a.id===val('f-a'));const rates=a.orderId?(await api('/api/order-items?orderId='+encodeURIComponent(a.orderId))).items.find(i=>i.equipmentId===a.equipmentId):null;document.getElementById('f-sale').value=rates?.saleRate??a.equipment.saleRate;document.getElementById('f-buy').value=rates?.purchaseRate??a.equipment.purchaseRate;document.getElementById('f-unit').value=rates?.unit||'shift'}}
async function searchPage(p){const d=await api('/api/search?archive=all&q='+encodeURIComponent(searchQuery));p.innerHTML=`<div class="page-head"><div><h1>Результаты поиска</h1><p>«${esc(searchQuery)}» · включая архив</p></div></div><h2>Компании</h2>${d.clients.map(c=>`<div class="card"><b>${esc(c.name)}</b> ${archiveBadge(c)}<p>${esc(c.inn)} · ${esc(c.phone)}</p><button class="btn btn-light search-company" data-id="${esc(c.id)}">Открыть в компаниях</button></div>`).join('')||empty()}<h2>Сделки</h2>${d.orders.map(o=>`<div class="card"><b>${esc(o.number)} · ${esc(o.name)}</b> ${archiveBadge(o)}<p>${esc(o.client)}</p><button class="btn btn-light search-order" data-id="${esc(o.id)}">Открыть сделку</button></div>`).join('')||empty()}`;p.querySelectorAll('.search-company').forEach(b=>b.onclick=()=>{current='clients';Object.assign(stateFor('clients'),{q:d.clients.find(c=>c.id===b.dataset.id).name,archive:'all'});renderApp()});p.querySelectorAll('.search-order').forEach(b=>b.onclick=()=>{current='orders';openOrderId=b.dataset.id;Object.assign(stateFor('orders'),{q:d.orders.find(o=>o.id===b.dataset.id).number,archive:'all'});renderApp()})}
function modal(title,body,onSave,saveText='Сохранить'){const previous=document.activeElement;modalRoot.innerHTML=`<div class="modal-backdrop"><form class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-head"><h3 id="modal-title">${esc(title)}</h3><button type="button" class="close-btn" aria-label="Закрыть">×</button></div><div class="modal-body">${body}</div><div class="form-error" role="alert"></div><div class="modal-foot"><button type="button" class="btn btn-light cancel">Отмена</button><button type="submit" class="btn btn-primary save">${esc(saveText)}</button></div></form></div>`;const form=modalRoot.querySelector('form'),save=form.querySelector('.save');const close=()=>{modalRoot.innerHTML='';previous?.focus()};form.querySelector('.close-btn').onclick=close;form.querySelector('.cancel').onclick=close;form.onkeydown=e=>{if(e.key==='Escape'){e.preventDefault();close()}if(e.key==='Tab'){const els=[...form.querySelectorAll('button,input,select,textarea')].filter(x=>!x.disabled);const first=els[0],last=els.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}};form.onsubmit=async e=>{e.preventDefault();if(save.disabled)return;save.disabled=true;try{await onSave();close();toast('Сохранено');await renderPage()}catch(e){form.querySelector('.form-error').textContent=e.message;save.disabled=false}};(form.querySelector('input,select,textarea')||form.querySelector('button'))?.focus()}

api('/api/session').then(r=>{if(!r||!r.user)throw new Error('Требуется вход');me=r.user;renderApp()}).catch(()=>{me=null;renderLogin()});

// Lead pipeline / follow-up control
const leadSources={call:'Входящий звонок',website:'Сайт',own:'Свой клиент',other:'Другое',email:'Почта',avito:'Авито',referral:'Рекомендация'};
const leadStates={new:'Новый',in_progress:'В работе',waiting:'Ожидание',qualified:'Квалифицирован',won:'Конвертирован',lost:'Отказ'};
async function leadsPage(p){
 const people=await api('/api/people');const [leads,attention,clientsAttention]=await Promise.all([api('/api/leads'),api('/api/leads?attention=yes'),api('/api/followups/clients?attention=yes')]);
 p.innerHTML=`<div class="page-head"><div><h1>Лиды</h1><p>Все обращения, история контактов и обязательный следующий шаг.</p></div><button class="btn btn-primary" id="create-lead">+ Добавить лид</button></div>
 <div class="kpi-grid"><div class="kpi"><div class="label">Всего лидов</div><div class="value">${leads.length}</div></div><div class="kpi"><div class="label">Лиды без движения</div><div class="value">${attention.length}</div></div><div class="kpi"><div class="label">Компании без контроля</div><div class="value">${clientsAttention.length}</div></div></div>
 ${attention.length?`<div class="code-note"><b>Контроль просрочек:</b> ${attention.length} лидов требуют действий. Сначала обработайте выделенные строки.</div>`:''}
 <div class="panel"><div class="table-wrap"><table class="table"><thead><tr><th>Клиент</th><th>Источник</th><th>Статус</th><th>Ответственный</th><th>Следующее действие</th><th>Последний контакт</th><th></th></tr></thead><tbody>${leads.map(l=>`<tr><td><b>${esc(l.name)}</b><div class="muted">${esc(l.company||'')} · ${esc(l.phone||'')}</div></td><td>${esc(leadSources[l.source]||l.source)}</td><td>${esc(leadStates[l.status]||l.status)}</td><td>${esc(l.owner)}</td><td><span style="${l.overdue||l.noNext?'color:#d84141;font-weight:bold':''}">${esc(l.nextAction||'Нет задачи')}<br>${esc(l.nextAt?new Date(l.nextAt).toLocaleString('ru-RU'):'Нет срока')}${l.overdue?' · ПРОСРОЧЕНО':''}</span></td><td>${esc(l.lastActivityAt?new Date(l.lastActivityAt).toLocaleString('ru-RU'):'—')}</td><td><button class="btn btn-light btn-sm lead-open" data-id="${esc(l.id)}">История / действие</button>${l.status!=='won'&&l.status!=='lost'?` <button class="btn btn-light btn-sm lead-convert" data-id="${esc(l.id)}">Связать с компанией</button>`:''}</td></tr>`).join('')}</tbody></table>${!leads.length?empty('Обращений пока нет'):''}</div></div>
 <div class="panel" style="margin-top:18px"><div class="panel-head"><h3>Контроль текущих клиентов</h3></div><p class="muted">Компания попадает сюда, если отсутствует запланированная задача или есть просрочка.</p><div class="table-wrap"><table class="table"><thead><tr><th>Компания</th><th>Ответственный</th><th>Контроль</th><th>Последнее действие</th><th></th></tr></thead><tbody>${clientsAttention.map(c=>`<tr><td><b>${esc(c.name)}</b><div class="muted">${esc(c.inn||'')} · ${esc(c.phone||'')}</div></td><td>${esc(c.manager)}</td><td><span style="color:#d84141">${c.overdue?`Просрочено задач: ${c.overdue}`:'Нет запланированной задачи'}</span></td><td>${esc(c.lastActivityAt?new Date(c.lastActivityAt).toLocaleString('ru-RU'):'—')}</td><td><button class="btn btn-light btn-sm open-attention-client" data-id="${esc(c.id)}">Открыть клиента</button></td></tr>`).join('')}</tbody></table>${!clientsAttention.length?empty('По текущим клиентам просрочек нет'):''}</div></div>`;
 p.querySelector('#create-lead').onclick=()=>leadForm(people);p.querySelectorAll('.open-attention-client').forEach(b=>b.onclick=()=>{current='clients';workspaceSelection={kind:'clients',id:b.dataset.id};renderApp()});
 p.querySelectorAll('.lead-open').forEach(b=>b.onclick=()=>leadDetail(b.dataset.id,people));
 p.querySelectorAll('.lead-convert').forEach(b=>b.onclick=async()=>{b.disabled=true;try{const converted=await api('/api/leads/'+encodeURIComponent(b.dataset.id)+'/convert',{method:'POST',body:'{}'});toast('Лид связан с компанией: '+(converted.client||converted.company||'готово'));await renderPage()}catch(e){toast(e.message,true);b.disabled=false}});
}
function leadForm(people){modal('Новый лид',`<div class="form-grid">${input('ld-name','Контакт / название', '', 'text',true)}${input('ld-phone','Телефон')}${input('ld-inn','ИНН')}${input('ld-company','Компания')}${select('ld-source','Источник',Object.entries(leadSources).map(([k,v])=>[k,v]),'own')}${select('ld-owner','Ответственный',people.map(x=>[x.id,x.name]),me.id)}${input('ld-action','Следующее действие','Позвонить клиенту','text',true)}${input('ld-due','Срок действия','','datetime-local',true)}${input('ld-note','Комментарий')}</div>`,()=>api('/api/leads',{method:'POST',body:JSON.stringify({name:val('ld-name'),phone:val('ld-phone'),inn:val('ld-inn'),company:val('ld-company'),source:val('ld-source'),ownerId:val('ld-owner'),nextAction:val('ld-action'),nextAt:val('ld-due'),note:val('ld-note')})}));}
async function leadDetail(id,people){const l=await api('/api/leads/'+id),events=await api('/api/leads/'+id+'/events');const ended=['won','lost'].includes(l.status);
 modal('Лид · '+l.name,`<p><b>Источник:</b> ${esc(leadSources[l.source]||l.source)} · <b>Ответственный:</b> ${esc(l.owner)}</p><p>${esc(l.phone||'')} · ${esc(l.company||'')}</p><h3>История контактов</h3><div style="max-height:220px;overflow:auto">${events.map(e=>`<div class="shift-row"><span><b>${esc(new Date(e.at).toLocaleString('ru-RU'))}</b> · ${esc(e.author)} · ${esc(e.type)}<div>${esc(e.text)}</div></span></div>`).join('')||empty('История пуста')}</div><hr><div class="form-grid">${select('ld-status','Статус',Object.entries(leadStates).map(([k,v])=>[k,v]),l.status)}${select('ld-owner','Ответственный',people.map(x=>[x.id,x.name]),l.ownerId)}${input('ld-action','Следующее действие',l.nextAction||'')}${input('ld-due','Срок',l.nextAt?.slice(0,16)||'','datetime-local')}${select('ld-event-type','Контакт',[['note','Комментарий'],['call','Звонок'],['meeting','Встреча'],['email','Письмо'],['message','Сообщение'],['task','Задача']],'call')}${input('ld-event-text','Результат контакта','')}</div>`,async()=>{const status=val('ld-status'),nextAction=val('ld-action'),nextAt=val('ld-due');await api('/api/leads/'+id,{method:'PATCH',body:JSON.stringify({status,ownerId:val('ld-owner'),nextAction,nextAt})});if(val('ld-event-text').trim())await api('/api/leads/'+id+'/events',{method:'POST',body:JSON.stringify({type:val('ld-event-type'),text:val('ld-event-text')})});},'Сохранить');}
